export function anchorStatus(anchor) {
  const statuses = anchor.shots.map(s => s.status)
  if (statuses.every(s => s === 'ready')) return 'ready'
  if (statuses.some(s => s === 'ready')) return 'pending'
  return 'blocked'
}

function statusOf(assetId) {
  const anchor = ANCHORS.find(a => a.id === assetId)
  if (anchor) return anchorStatus(anchor)
  const found = [...LOCATIONS, ...VEHICLES].find(a => a.id === assetId)
  return found?.status ?? 'blocked'
}

export function shotReadiness(shot) {
  const statuses = shot.needs.map(statusOf)
  if (statuses.every(s => s === 'ready')) return 'ready'
  if (statuses.some(s => s === 'blocked')) return 'blocked'
  return 'pending'
}

export function projectSummary() {
  const allAssets = [
    ...ANCHORS.flatMap(a => a.shots.map(s => ({ ...s, kind: 'anchor', parent: a.name }))),
    ...LOCATIONS.map(l => ({ ...l, kind: 'location' })),
    ...VEHICLES.map(v => ({ ...v, kind: 'vehicle' })),
  ]
  const ready = allAssets.filter(a => a.status === 'ready').length
  return { total: allAssets.length, ready, pending: allAssets.length - ready }
}
